import{_ as e,o as t,c as a,a5 as i}from"./chunks/framework.BPFk9-tb.js";const d=JSON.parse('{"title":"vShell 0.2.0 发布：新界面","description":"","frontmatter":{"title":"vShell 0.2.0 发布：新界面","date":"2026-10-08T08:00:14","categories":["course100"],"tags":["vShell"]},"headers":[{"level":2,"title":"一、界面重写：窗口是画布，面板是岛","slug":"一、界面重写-窗口是画布-面板是岛","link":"#一、界面重写-窗口是画布-面板是岛","children":[]},{"level":2,"title":"二、多开终端「连坐断开」的 Bug，修了","slug":"二、多开终端「连坐断开」的-bug-修了","link":"#二、多开终端「连坐断开」的-bug-修了","children":[]},{"level":2,"title":"三、终于有安装包了","slug":"三、终于有安装包了","link":"#三、终于有安装包了","children":[]},{"level":2,"title":"四、其他","slug":"四、其他","link":"#四、其他","children":[]},{"level":2,"title":"下载与链接","slug":"下载与链接","link":"#下载与链接","children":[]}],"relativePath":"posts/course100/067.md","filePath":"posts/course100/067.md"}'),s={name:"posts/course100/067.md"};function r(n,l,o,p,h,g){return t(),a("div",null,[...l[0]||(l[0]=[i(`<p>新版本主要做了三件事：把整个界面重写成「岛式（Islands）」设计语言；修掉一个多开终端时会「连坐断开」的 Bug；第一次提供了三大平台的安装包。下面挨个说说。</p><h2 id="一、界面重写-窗口是画布-面板是岛" tabindex="-1">一、界面重写：窗口是画布，面板是岛 <a class="header-anchor" href="#一、界面重写-窗口是画布-面板是岛" aria-label="Permalink to &quot;一、界面重写：窗口是画布，面板是岛&quot;">​</a></h2><p>新版本把整个窗口当作一张<strong>画布</strong>，所有内容面板 —— 终端区、左侧连接树、底部的 SFTP 与监控 —— 都是浮在画布上的<strong>圆角岛</strong>，岛与岛之间统一留 6px 接缝。工具栏、左条、状态栏则与画布同色，融为一体，只做低调的外框。</p><p>不只是换个圆角，背后是一套完整的规范，捡几条说：</p><ul><li><p><strong>工具优先，内容至上</strong> —— 铬框低调，焦点留给终端会话与文件操作；</p></li><li><p><strong>一切皆 Token</strong> —— 颜色、度量全部出自单一事实源，浅色 / 深色镜像命名，切换主题零结构变化；</p></li><li><p><strong>灰阶为主体，单一品牌蓝做强调</strong> —— 彩色只用于选中、焦点、链接和连接状态；</p></li><li><p><strong>会话是一等公民</strong> —— 标签即会话，切换不丢缓冲，连接状态点常显；</p></li><li><p><strong>连接状态可视化</strong> —— connecting / online / offline / error 四态，在连接树、标签、状态栏三处同色出现，一眼可辨。</p></li></ul><p>这套设计语言以 IntelliJ IDEA 的灰阶体系和 Token 纪律为源头，再针对 SSH 客户端形态定制。完整规范已发布在文档站「设计规范 → 设计语言」，往后界面怎么改都有章可循。</p><h2 id="二、多开终端「连坐断开」的-bug-修了" tabindex="-1">二、多开终端「连坐断开」的 Bug，修了 <a class="header-anchor" href="#二、多开终端「连坐断开」的-bug-修了" aria-label="Permalink to &quot;二、多开终端「连坐断开」的 Bug，修了&quot;">​</a></h2><p>先说现象：对同一个连接反复「打开」，开到第 10 个左右的标签时，<strong>前面所有终端同时断开</strong>，只剩最新那一个能用。</p><p>它和 SSH 多路复用有关：</p><ol><li><p>vShell 里，同一连接的所有终端复用<strong>一条</strong> SSH 连接（多路复用，这是省资源的好设计）；</p></li><li><p>但 OpenSSH 服务端默认 <code>MaxSessions = 10</code> —— 单条连接上最多 10 个会话通道，每个终端标签占 1 个，SFTP 面板还要占 1 个；</p></li><li><p>超限时，服务端会拒绝建立新会话（<code>administratively prohibited</code>）；</p></li><li><p>旧版代码把一切「新建会话失败」都当作「这条连接已经死了」，于是关闭旧连接、重新拨号；</p></li><li><p>结果：旧连接一关，上面所有终端被服务端顺手断开 —— 全部「连坐」，而新连接只服务最新的那个标签。</p></li></ol><p>修复思路是<strong>给错误分类</strong>：</p><ul><li><p><strong>连接级错误</strong>（EOF、连接重置、传输层死亡）：保留原有的「驱逐重拨」自愈逻辑 —— 正是它让服务端空闲断开后能无缝重连；</p></li><li><p><strong>服务端拒绝新会话</strong>：不关连接、不重拨，直接弹窗告知「服务端 MaxSessions 限制」，已打开的终端毫发无伤。</p></li></ul><h2 id="三、终于有安装包了" tabindex="-1">三、终于有安装包了 <a class="header-anchor" href="#三、终于有安装包了" aria-label="Permalink to &quot;三、终于有安装包了&quot;">​</a></h2><p>新版本配好了 GitHub Actions 自动打包，Release 页面直接下载：</p><ul><li><p><strong>macOS</strong>：通用二进制（Apple Silicon / Intel 一份包通吃）</p></li><li><p><strong>Windows</strong>：NSIS 安装包 + 便携版</p></li><li><p><strong>Linux</strong>：deb / rpm / 便携版</p></li></ul><p>一个提醒：macOS 包暂未做公证，首次打开若被拦截，右键 App →「打开」，或执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/vshell.app</span></span></code></pre></div><h2 id="四、其他" tabindex="-1">四、其他 <a class="header-anchor" href="#四、其他" aria-label="Permalink to &quot;四、其他&quot;">​</a></h2><ul><li><p><strong>Wails v3 升级至 v3.0.0-beta.28</strong>；</p></li><li><p><strong>文档站</strong>：新增「更新记录」页；首页与导航加入下载入口；补齐 HTTPS 证书管理指南（acme.sh 远程签发 / 续签）；设计语言规范上线。</p></li></ul><h2 id="下载与链接" tabindex="-1">下载与链接 <a class="header-anchor" href="#下载与链接" aria-label="Permalink to &quot;下载与链接&quot;">​</a></h2><ul><li><p>下载：<a href="https://github.com/crazy-airhead/vshell/releases/latest" target="_blank" rel="noreferrer">https://github.com/crazy-airhead/vshell/releases/latest</a></p></li><li><p>文档：<a href="https://crazy-airhead.github.io/vshell/" target="_blank" rel="noreferrer">https://crazy-airhead.github.io/vshell/</a></p></li><li><p>源码：<a href="https://github.com/crazy-airhead/vshell" target="_blank" rel="noreferrer">https://github.com/crazy-airhead/vshell</a></p></li></ul><p>最后照例介绍一句：vShell 是一个纯本地的桌面 SSH 客户端（Wails 3 = Go + Vue 3），终端、SFTP、服务器监控、远程文件编辑、SSH 密钥管理、端口转发、HTTPS 证书管理都有 —— 无云端、无账号、无遥测。如果你在找一个 FinalShell 的替代品，可以试试。</p><p>有问题欢迎在 GitHub Issues 反馈。</p>`,23)])])}const u=e(s,[["render",r]]);export{d as __pageData,u as default};
